package com.collabspace.config; import com.collabspace.entity.*;import com.collabspace.repository.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder; @Configuration public class SeedData { @Bean CommandLineRunner seed(UserRepository users,WorkspaceRepository ws,WorkspaceMemberRepository wm,ChannelRepository channels,ChannelMemberRepository cm,MessageRepository messages,PasswordEncoder enc,@Value("${SEED_DATA:false}")boolean enabled){return args->{if(!enabled||users.count()>0)return;User admin=users.save(User.builder().username("admin").email("admin@example.com").password(enc.encode("Admin@12345")).role(Role.ADMIN).build());User user=users.save(User.builder().username("user").email("user@example.com").password(enc.encode("User@12345")).build());Workspace w=ws.save(Workspace.builder().name("CollabSpace Demo").description("Development workspace").owner(admin).build());wm.save(WorkspaceMember.builder().workspace(w).user(admin).role(WorkspaceRole.OWNER).build());wm.save(WorkspaceMember.builder().workspace(w).user(user).role(WorkspaceRole.MEMBER).build());Channel c=channels.save(Channel.builder().workspace(w).name("general").description("Company-wide conversation").createdBy(admin).build());cm.save(ChannelMember.builder().channel(c).user(admin).build());cm.save(ChannelMember.builder().channel(c).user(user).build());messages.save(Message.builder().channel(c).sender(admin).content("Welcome to CollabSpace 👋").build());messages.save(Message.builder().channel(c).sender(user).content("Real-time collaboration is ready!").build());};}}